import { z } from "zod";

/**
 * 1. Research Planning Schema
 * Generated by the initial LLM call to break down the user's natural language query.
 */
export const ResearchPlanSchema = z.object({
  query: z.string().describe("The normalized primary research question."),
  category: z.string().describe("Broad product category (e.g., 'Electronics')."),
  niche: z.string().describe("Specific product niche (e.g., 'Smartphones')."),
  market: z.string().describe("Target geographic market or 'Worldwide'."),
  targetCount: z.number().describe("The number of final candidates the user requested."),
  searchQueries: z.array(z.string()).describe("3-5 highly optimized Google Search queries to discover candidates and evidence."),
  requiredMetrics: z.array(z.string()).describe("Key specs/metrics that must be gathered for these products (e.g., 'Battery Life', 'Screen Size')."),
  rankingCriteria: z.string().describe("A brief explanation of how products should be ranked (e.g., 'Best overall value and performance')."),
});

export type ResearchPlan = z.infer<typeof ResearchPlanSchema>;

/**
 * 2. Extraction Schema
 * Used by Groq to extract structured product data from a block of raw HTML/text.
 */
export const ExtractedProductSchema = z.object({
  modelName: z.string().describe("The exact, disambiguated product model name."),
  brand: z.string(),
  price: z.number().nullable().describe("Extracted price in USD, or null if not found."),
  currency: z.string().nullable().describe("Original currency code, if found."),
  features: z.record(z.string(), z.string()).describe("Key-value pairs of extracted specs (e.g., { 'Battery': '5000mAh' })."),
  rating: z.number().nullable().describe("Review rating out of 5.0, if found."),
});

export type ExtractedProduct = z.infer<typeof ExtractedProductSchema>;

/**
 * 3. Final Report Synthesis Schema
 * Generated at the end to provide explanations for the data.
 */
export const ReportSynthesisSchema = z.object({
  executiveSummary: z.string(),
  marketInsights: z.object({
    trendDescription: z.string(),
    sentiment: z.string(),
    priceVolatility: z.string(),
  }),
  futureScenarios: z.array(z.object({
    scenario: z.string(),
    description: z.string(),
  })),
  businessOpportunity: z.string(),
});

export type ReportSynthesis = z.infer<typeof ReportSynthesisSchema>;
